"""Error catalog (spec §54) — generated by hand from the specification.

Each user-facing error MUST provide: summary, data impact, recommended action,
diagnostics affordance and a stable code. Stack traces belong in "Developer
details" only. Codes are stable: never renumber, only append.
"""

from __future__ import annotations

from dataclasses import dataclass

from acet.domain.enums import FailureFamily, OperationOutcome


@dataclass(frozen=True)
class ErrorSpec:
    code: str
    summary: str
    family: FailureFamily
    outcome: OperationOutcome
    impact: str
    action: str


def _e(
    code: str, summary: str, family: FailureFamily, outcome: OperationOutcome, impact: str, action: str
) -> ErrorSpec:
    return ErrorSpec(code, summary, family, outcome, impact, action)


