class AcetError(Exception):
    """Error carrying a stable catalog code (ACET-CLOSE-002/003)."""

    def __init__(self, code: str, detail: str | None = None, *, data: dict[str, object] | None = None) -> None:
        spec = CATALOG.get(code)
        if spec is None:
            spec = CATALOG["ACET-INT-001"]
            detail = f"unknown error code {code!r}: {detail}"
        self.spec = spec
        self.code = spec.code
        self.detail = detail
        self.data = dict(data or {})
        super().__init__(f"{spec.code}: {spec.summary}" + (f" — {detail}" if detail else ""))

    @property
    def family(self) -> FailureFamily:
        return self.spec.family

    @property
    def outcome(self) -> OperationOutcome:
        return self.spec.outcome

    def to_dict(self) -> dict[str, object]:
        return {
            "code": self.code,
            "summary": self.spec.summary,
            "detail": self.detail,
            "family": self.family.value,
            "outcome": self.outcome.value,
            "impact": self.spec.impact,
            "action": self.spec.action,
            **({"data": self.data} if self.data else {}),
        }


def classify_exception(exc: BaseException) -> AcetError:
    """Map any exception onto the closed taxonomy (ACET-CLOSE-002, ACC-103)."""
    from acet.domain.state_machines import DomainTransitionError

    if isinstance(exc, AcetError):
        return exc
    if isinstance(exc, DomainTransitionError):
        return AcetError("ACET-DOM-001", str(exc))
    if isinstance(exc, FileNotFoundError | PermissionError | IsADirectoryError):
        return AcetError("ACET-IMP-001", type(exc).__name__)
    if isinstance(exc, OSError) and getattr(exc, "errno", None) == 28:  # ENOSPC
        return AcetError("ACET-IMP-003", "ENOSPC")
    return AcetError("ACET-INT-001", f"{type(exc).__name__}: {exc}")
